    "IsolateHost": {
      "Type": "Task",
      "Resource": "arn:aws:lambda:...:function:isolate-sap-host",
      "Next": "RotateCredentials"
    },
    "RotateCredentials": {
      "Type": "Task",
      "Resource": "arn:aws:lambda:...:function:rotate-sap-secrets",
      "Next": "NotifyAndLog"
    },
    "NotifyAndLog": {
      "Type": "Task",
      "Resource": "arn:aws:lambda:...:function:notify-and-log",
      "End": true
    },
    "LogAndDismiss": {
      "Type": "Pass",
      "End": true
    }
