## Minimal IaC Sketch (Terraform)
```hcl
resource "aws_sfn_state_machine" "sap_incident_response" {
  name     = "sap-incident-response"
  role_arn = aws_iam_role.stepfunctions_role.arn
  definition = file("${path.module}/state_machine.json")
}

resource "aws_iam_role" "cross_account_remediation" {
  name = "sap-remediation-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17",
    Statement = [{
      Effect = "Allow",
      Principal = { AWS = "arn:aws:iam::123456789:role/sap-incident-response-role" },
      Action = "sts:AssumeRole",
      Condition = { Bool = { "aws:MultiFactorAuthPresent" = true } }
    }]
  })
}

resource "aws_security_group_rule" "sap_isolation" {
  count = 1
  type        = "ingress"
  from_port   = 0
  to_port     = 0
  protocol    = "-1"
  description = "Emergency isolation"
  source_security_group_id = aws_security_group.sap_management.id
}
```

